class Solution(object):
    def projectionArea(self, grid):
        """
        :type grid: List[List[int]]
        :rtype: int
        """
        n = len(grid)
        area1 = 0
        for i in range(n):
            for j in range(n):
                if grid[i][j] != 0:
                    area1 += 1
        area2 = 0
        for i in range(n):
            area2 += max(grid[i])
        area3 = 0
        for j in range(n):
            area3 += max([grid[i][j] for i in range(n)])
        return area1 + area2 + area3
